{{!-- Styling parameters: class, buttonClass --}}
{{#with this as |ghostcnStyles|}}
<div class="ghcn-theme-toggle{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-ghcn-theme-toggle data-variant="{{#match variant "compact"}}compact{{else}}{{#match variant "outline"}}outline{{else}}default{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}" role="group" aria-label="{{#if ariaLabel}}{{ariaLabel}}{{else}}Color theme{{/if}}">
  {{#match variant "compact"}}
    <button type="button" class="ghcn-theme-toggle__btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-theme-toggle__btn--cycle" data-theme-cycle aria-label="Toggle color theme"><svg class="ghcn-theme-toggle__sun" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="10" cy="10" r="3.5"/><path d="M10 2.5v1.5M10 16v1.5M4.7 4.7l1.1 1.1M14.2 14.2l1.1 1.1M2.5 10H4M16 10h1.5M4.7 15.3l1.1-1.1M14.2 5.8l1.1-1.1"/></svg><svg class="ghcn-theme-toggle__moon" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M16.5 12.2A6.5 6.5 0 0 1 7.8 3.5a6.5 6.5 0 1 0 8.7 8.7Z"/></svg></button>
  {{else}}{{#match variant "outline"}}
    <button type="button" class="ghcn-theme-toggle__btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-theme-toggle__btn--cycle" data-theme-cycle aria-label="Toggle color theme"><svg class="ghcn-theme-toggle__sun" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="10" cy="10" r="3.5"/><path d="M10 2.5v1.5M10 16v1.5M4.7 4.7l1.1 1.1M14.2 14.2l1.1 1.1M2.5 10H4M16 10h1.5M4.7 15.3l1.1-1.1M14.2 5.8l1.1-1.1"/></svg><svg class="ghcn-theme-toggle__moon" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M16.5 12.2A6.5 6.5 0 0 1 7.8 3.5a6.5 6.5 0 1 0 8.7 8.7Z"/></svg><span data-theme-label>Theme</span></button>
  {{else}}
    <button type="button" class="ghcn-theme-toggle__btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" data-theme-value="light" aria-label="Light theme" aria-pressed="false"><svg class="ghcn-theme-toggle__sun" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="10" cy="10" r="3.5"/><path d="M10 2.5v1.5M10 16v1.5M4.7 4.7l1.1 1.1M14.2 14.2l1.1 1.1M2.5 10H4M16 10h1.5M4.7 15.3l1.1-1.1M14.2 5.8l1.1-1.1"/></svg></button>
    <button type="button" class="ghcn-theme-toggle__btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" data-theme-value="system" aria-label="System theme" aria-pressed="false"><svg class="ghcn-theme-toggle__system" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="3.5" width="15" height="10" rx="1.5"/><path d="M7 16.5h6M10 13.5v3"/></svg></button>
    <button type="button" class="ghcn-theme-toggle__btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" data-theme-value="dark" aria-label="Dark theme" aria-pressed="false"><svg class="ghcn-theme-toggle__moon" aria-hidden="true" viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M16.5 12.2A6.5 6.5 0 0 1 7.8 3.5a6.5 6.5 0 1 0 8.7 8.7Z"/></svg></button>
  {{/match}}{{/match}}
</div>
{{/with}}

.ghcn-theme-toggle { box-sizing: border-box; display: inline-flex; align-items: center; gap: 2px; padding: 3px; border: 1px solid var(--border); border-radius: 9999px; background: var(--secondary); color: var(--foreground); font-family: inherit; font-size: var(--ghcn-text-small, 14px); line-height: 1; }
.ghcn-theme-toggle *, .ghcn-theme-toggle *::before, .ghcn-theme-toggle *::after { box-sizing: border-box; }
.ghcn-theme-toggle:where([data-variant="compact"]), .ghcn-theme-toggle:where([data-variant="outline"]) { padding: 0; background: transparent; border-color: transparent; }
.ghcn-theme-toggle__btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-width: 32px; height: 32px; padding: 0 8px; border: 1px solid transparent; border-radius: 9999px; background: transparent; color: var(--muted-foreground); font: inherit; font-weight: 600; cursor: pointer; transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease; }
.ghcn-theme-toggle:where([data-size="sm"]) .ghcn-theme-toggle__btn { min-width: 28px; height: 28px; padding: 0 6px; font-size: 12px; }
.ghcn-theme-toggle:where([data-size="lg"]) .ghcn-theme-toggle__btn { min-width: 38px; height: 38px; padding: 0 12px; font-size: 15px; }
.ghcn-theme-toggle__btn:hover { color: var(--foreground); }
.ghcn-theme-toggle__btn[aria-pressed="true"] { background: var(--background); color: var(--foreground); border-color: var(--border); box-shadow: 0 1px 2px #0001; }
.ghcn-theme-toggle:where([data-variant="compact"]) .ghcn-theme-toggle__btn--cycle,
.ghcn-theme-toggle:where([data-variant="outline"]) .ghcn-theme-toggle__btn--cycle { border-color: var(--border); background: var(--card); color: var(--foreground); border-radius: var(--ghcn-control-radius, var(--radius, 8px)); padding: 0 10px; }
.ghcn-theme-toggle:where([data-variant="compact"]) .ghcn-theme-toggle__btn--cycle { padding: 0; }
.ghcn-theme-toggle:where([data-variant="compact"]) .ghcn-theme-toggle__btn--cycle:hover,
.ghcn-theme-toggle:where([data-variant="outline"]) .ghcn-theme-toggle__btn--cycle:hover { background: var(--muted); }
.ghcn-theme-toggle__btn--cycle .ghcn-theme-toggle__moon { display: none; }
.ghcn-theme-toggle[data-resolved="dark"] .ghcn-theme-toggle__btn--cycle .ghcn-theme-toggle__sun { display: none; }
.ghcn-theme-toggle[data-resolved="dark"] .ghcn-theme-toggle__btn--cycle .ghcn-theme-toggle__moon { display: block; }
.ghcn-theme-toggle:focus-visible, :where(.ghcn-theme-toggle) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .ghcn-theme-toggle__btn { transition: none; } }

/* ghostcn theme toggle: persists light/dark/system preference, repeat-safe, no dependencies. */
(() => {
  const KEY = 'ghcn-theme';
  const root = document.documentElement;
  const media = window.matchMedia('(prefers-color-scheme: dark)');

  function readPreference() {
    try {
      const saved = localStorage.getItem(KEY);
      if (saved === 'light' || saved === 'dark' || saved === 'system') return saved;
    } catch {}
    if (root.classList.contains('dark-mode') || root.classList.contains('dark')) return 'dark';
    if (root.classList.contains('auto-color')) return 'system';
    return 'light';
  }

  function applyTheme(mode, persist) {
    const resolved = mode === 'system' ? (media.matches ? 'dark' : 'light') : mode;
    root.classList.toggle('auto-color', mode === 'system');
    root.classList.toggle('dark-mode', resolved === 'dark');
    root.classList.toggle('dark', resolved === 'dark');
    root.setAttribute('data-theme', resolved);
    if (persist) {
      try { localStorage.setItem(KEY, mode); } catch {}
    }
    document.querySelectorAll('[data-ghcn-theme-toggle]').forEach(container => {
      container.dataset.mode = mode;
      container.dataset.resolved = resolved;
      container.querySelectorAll('[data-theme-value]').forEach(btn => {
        btn.setAttribute('aria-pressed', String(btn.dataset.themeValue === mode));
      });
      const cycle = container.querySelector('[data-theme-cycle]');
      if (cycle) {
        const next = resolved === 'dark' ? 'light' : 'dark';
        cycle.setAttribute('aria-label', 'Switch to ' + next + ' theme');
        const label = cycle.querySelector('[data-theme-label]');
        if (label) label.textContent = resolved === 'dark' ? 'Dark' : 'Light';
      }
    });
  }

  function init() {
    const mode = readPreference();
    applyTheme(mode, false);
    document.querySelectorAll('[data-ghcn-theme-toggle]').forEach(container => {
      if (container.dataset.ghcnThemeReady) return;
      container.dataset.ghcnThemeReady = 'true';
      container.querySelectorAll('[data-theme-value]').forEach(btn => {
        btn.addEventListener('click', () => applyTheme(btn.dataset.themeValue, true));
      });
      const cycle = container.querySelector('[data-theme-cycle]');
      if (cycle) {
        cycle.addEventListener('click', () => {
          const isDark = root.classList.contains('dark-mode') || root.classList.contains('dark');
          applyTheme(isDark ? 'light' : 'dark', true);
        });
      }
    });
    media.addEventListener?.('change', () => {
      if (readPreference() === 'system') applyTheme('system', false);
    });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
